using namespace midnightNative;
class V01Application:public OrganicApplication {public:V01Application():OrganicApplication("Midnight V01 acceptance",false){}void initialiseInternal(const String&)override{}};
static int checks=0;
static void check(bool ok,const char* label){if(!ok)throw std::runtime_error(label);++checks;std::cout<<"PASS "<<label<<std::endl;}
static void pump(int ms){auto end=monotonic()+ms/1000.;while(monotonic()<end){MSG msg;while(PeekMessageW(&msg,nullptr,0,0,PM_REMOVE)){TranslateMessage(&msg);DispatchMessageW(&msg);}Thread::sleep(1);}}
static void waitFor(const std::function<bool()>& predicate,const char* label,int ms=6000){auto end=monotonic()+ms/1000.;while(monotonic()<end&&!predicate())pump(10);check(predicate(),label);}
static void screenshot(Component& c,const File& file){auto image=c.createComponentSnapshot(c.getLocalBounds());FileOutputStream out(file);out.setPosition(0);out.truncate();PNGImageFormat png;check(png.writeImageToStream(image,out),"actual native component screenshot saved");}
template<class T>static T* findControl(Component& root,const String& name){if(auto* control=dynamic_cast<T*>(&root))if(control->getName()==name)return control;for(auto* child:root.getChildren())if(auto* found=findControl<T>(*child,name))return found;return nullptr;}
static TextButton* findButton(Component& root,const String& text){if(auto* button=dynamic_cast<TextButton*>(&root))if(button->getButtonText()==text)return button;for(auto* child:root.getChildren())if(auto* found=findButton(*child,text))return found;return nullptr;}
int main(int argc,char** argv){if(argc!=3)return 2;ScopedJuceInitialiser_GUI gui;V01Application app;app.engine.reset(new ChataigneEngine());app.mainComponent.reset(new MainContentComponent());app.appProperties->getUserSettings()->setValue("lastVersion",ProjectInfo::versionString);app.mainComponent->init();app.engine->createNewGraph();int code=0;
    try{
        bool reload=String(argv[1])=="reload";File path(String::fromUTF8(argv[2]));auto* s=service();check(s!=nullptr,"native engine owns Midnight adapter");
        if(reload){check(app.engine->loadFrom(path,false).wasOk(),"native document load accepted");waitFor([&]{return !app.engine->isLoadingFile;},"asynchronous native document load finished");}
        else{s->edit(demonstration());}
        waitFor([&]{auto snap=s->snapshot();if(snap.document.motors.size()!=3)return false;for(auto& m:snap.document.motors)if(snap.motors[m.id].at<0)return false;return true;},"one shared simulated adapter routes mechanical feedback to three motors");
        auto doc=s->snapshot().document;auto m0=doc.motors[0].id,m1=doc.motors[1].id,m2=doc.motors[2].id;Id main=doc.events[0].id,slow=doc.events[1].id,fast=doc.events[3].id,nested=doc.events[5].id,link=doc.events[7].id,haptic=doc.events[8].id;
        if(reload)check(doc.motors[0].name=="Renamed cupboard"&&doc.events[0].name=="Renamed timeline","fresh process reload retains display names without changing references");
        if(reload)check(doc.motors[0].min==-20&&doc.events[8].stiffness==1.7&&doc.events[8].damping==.08&&doc.events[8].torqueLimit==.6&&doc.events[8].signB==-1,"native reload retains custom bounds and haptic parameters");
        auto snap=s->snapshot();check(snap.adapters.size()==1,"exactly one transport for all three motors");check(!snap.armed,"load never arms execution");for(auto& p:snap.events)check(p.second.status!=Status::Running,"load never resumes an event");check(!snap.motors[m0].enableSent,"observation connection sends no enable");
        check(doc.motors[1].model=="RS01"&&doc.motors[0].model=="RS02","model assignments survive native persistence");
        {auto editor=createMotorEditor(m0);editor->setSize(820,850);auto* minimum=findControl<TextEditor>(*editor,"MIN target / mechanical degrees");auto* save=findButton(*editor,"Save motor settings");check(minimum&&save,"actual motor editor exposes saved MIN and direct Save controls");minimum->setText("-20");save->onClick();auto edited=s->snapshot();check(edited.document.adapters[0].simulated&&edited.document.motors[0].adapter==doc.adapters[0].id,"saving a reused simulated adapter preserves its identity and transport type");check(edited.document.motors[0].min==-20&&!edited.motors[m0].enableSent,"typed MIN saves through actual editor without enable or zero");doc=edited.document;auto* target=findControl<TextEditor>(*editor,"Target / mechanical degrees");auto* move=findButton(*editor,"Move to Position");auto* error=findControl<Label>(*editor,"Motor action status");check(target&&move&&error,"motor test controls expose local command errors");target->setText("999");move->onClick();waitFor([&]{return error->getText().contains("MIN/MAX");},"direct target error appears inside the motor dialog");}
        s->action([&](Runtime& r){r.move(m0,15,90);});waitFor([&]{return std::abs(s->snapshot().motors[m0].position-15)<.5;},"Connect -> direct Move reaches simulated target");
        s->action([&](Runtime& r){r.stopMotor(m0);r.move(m0,0,90);});waitFor([&]{return std::abs(s->snapshot().motors[m0].position)<.5;},"Stop/Disable -> subsequent deliberate Move works");
        s->action([](Runtime& r){r.stopAll();});
        DatagramSocket artnet;check(artnet.bindToPort(0,"127.0.0.1"),"loopback Art-Net receiver bound");doc.dmxPort=artnet.getBoundPort();s->edit(doc);
        NativePanel panel("MIDNIGHT SHOW CONTROL");panel.setSize(1400,940);panel.navigate(main);panel.selected=fast;
        s->resetMetrics();s->action([&](Runtime& r){r.arm();r.go(main);});
        waitFor([&]{return s->snapshot().events[fast].status==Status::Completed;},"native worker executes measured-position supersession and feedback completion",8000);
        snap=s->snapshot();check(snap.events[slow].status==Status::Superseded,"old slow movement is distinctly superseded");check(snap.motors[m0].enableSent,"new movement keeps motor active after completion");
        double crossingAt=-1,targetAt=-1,previousPosition=0;bool hasPrevious=false;
        for(auto& entry:snap.monitor){std::istringstream line(entry);double at;std::string direction,wire;line>>at>>direction>>wire;Frame f;if(!parseSlcan(wire,f))continue;
            if(direction=="RX"&&f.id==read(254,126).id&&f.data[0]==0x19&&f.data[1]==0x70){double position=degrees(decodeFloat(f));if(hasPrevious&&previousPosition<10&&position>=10)crossingAt=at;previousPosition=position;hasPrevious=true;}
            if(crossingAt>=0&&direction=="TX"&&f.id==write(126,254,0x7016,0,"RS02").id&&f.data[0]==0x16&&f.data[1]==0x70&&std::abs(degrees(decodeFloat(f))-45)<.001){targetAt=at;break;}
        }
        check(crossingAt>=0&&targetAt>=crossingAt,"measured crossing RX and replacement target TX are timestamped independently");
        bool sawDMX=false;int packets=0,lastValue=-1;std::array<uint8,1024> bytes{};auto until=monotonic()+2;while(monotonic()<until){pump(10);if(artnet.waitUntilReady(true,1)>0){int n=artnet.read(bytes.data(),int(bytes.size()),false);++packets;if(n>=20){lastValue=bytes[18];if(std::memcmp(bytes.data(),"Art-Net",7)==0&&bytes[18]==200){sawDMX=true;break;}}}}if(!sawDMX)std::cerr<<"DMX diagnostics: packets="<<packets<<" last="<<lastValue<<" event="<<statusName(s->snapshot().events[doc.events[4].id].status)<<" error="<<s->snapshot().error<<std::endl;check(sawDMX,"actual Chataigne DMX module emits position-triggered Art-Net value on loopback");
        waitFor([&]{return s->snapshot().events[doc.events[6].id].status==Status::Completed;},"native clock executes nested timeline child",7000);
        panel.update();auto evidence=path.getParentDirectory().getParentDirectory().getChildFile("evidence");screenshot(panel,evidence.getChildFile("v01-timeline.png"));
        panel.navigate(nested);screenshot(panel,evidence.getChildFile("v01-nested-timeline.png"));panel.navigate(main);
        auto adaptive=createEventEditor(haptic);adaptive->setSize(920,1400);screenshot(*adaptive,evidence.getChildFile("v01-adaptive-editor.png"));adaptive.reset();
        {auto editor=createEventEditor(haptic);editor->setSize(920,860);auto* remove=findButton(*editor,"Remove this condition");check(remove!=nullptr,"adaptive haptic editor exposes its deactivation rule");remove->onClick();pump(5);check(findButton(*editor,"Remove this condition")==nullptr,"removing a condition also removes its button safely");auto* apply=findButton(*editor,"Apply event");check(apply!=nullptr,"adaptive editor exposes Apply");apply->onClick();check(s->snapshot().document.events[8].out.empty(),"adaptive editor applies changed deactivation rules to executable definition");s->edit(doc);}
        {panel.selected=main;findButton(panel,"Copy")->onClick();panel.navigate({});findButton(panel,"Paste")->onClick();auto copied=s->snapshot().document;check(copied.events.size()==doc.events.size()+7,"actual Copy/Paste callbacks clone the timeline and all descendants");auto root=copied.events[doc.events.size()].id;check(root!=main&&copied.events[doc.events.size()+1].parent==root,"pasted boxes have independent IDs and remapped parent references");panel.selected=root;findButton(panel,"Remove selected")->onClick();check(s->snapshot().document.events.size()==doc.events.size(),"removing a copied timeline preserves its original");panel.navigate(main);}
        s->action([&](Runtime& r){r.stopAll();});s->injectPosition(m0,20);pump(50);s->action([&](Runtime& r){r.go(link);});
        waitFor([&]{auto p=s->snapshot();return std::abs(p.motors[m1].position-20)<.5&&std::abs(p.motors[m2].position-20)<.5;},"one master plus two followers execute through shared packet loopback");
        s->action([&](Runtime& r){r.stop(link);r.go(haptic);});waitFor([&]{auto p=s->snapshot();return p.motors[m0].torqueMode&&p.motors[m0].enableSent&&p.motors[m1].enableSent;},"one-to-one haptic setup sends mode and enable sequence");
        s->injectPosition(m0,25);waitFor([&]{auto p=s->snapshot();return std::abs(p.motors[m0].commandedTorque)>.01&&std::abs(p.motors[m1].commandedTorque)>.01;},"new measured displacement drives continuous nonzero coupling packets for both motors");
        // GUI load: redraw, serialize, rename with stable IDs, and simulate a blocked GUI.
        for(int i=0;i<30;++i){panel.update();panel.createComponentSnapshot(panel.getLocalBounds());JSON::toString(s->save());pump(5);}auto before=s->snapshot().metrics.loops;Thread::sleep(250);auto after=s->snapshot().metrics.loops;check(after>before+10,"continuous worker advances while GUI thread is blocked");
        auto metrics=s->snapshot().metrics;var report(new DynamicObject());auto* o=report.getDynamicObject();o->setProperty("scope","Three fake motors, real production C++ bus/worker and GUI activity; no physical serial device");o->setProperty("loops",int64(metrics.loops));o->setProperty("interval_mean_ms",metrics.intervalMean*1000);o->setProperty("interval_max_ms",metrics.intervalMax*1000);o->setProperty("max_interval_excess_over_mean_ms",(metrics.intervalMax-metrics.intervalMean)*1000);o->setProperty("position_crossing_rx_to_target_tx_ms",(targetAt-crossingAt)*1000);o->setProperty("enqueue_to_write_max_ms",metrics.transmitDelayMax*1000);o->setProperty("queue_max",int(metrics.queueMax));o->setProperty("feedback_age_max_ms_at_snapshot",metrics.feedbackAgeMax*1000);o->setProperty("tx",int64(metrics.tx));o->setProperty("rx",int64(metrics.rx));evidence.getChildFile("v01-worker-metrics.json").replaceWithText(JSON::toString(report));
        s->injectPosition(m0,61);waitFor([&]{auto p=s->snapshot();return p.events[haptic].status==Status::Stopped&&!p.motors[m0].enableSent&&!p.motors[m1].enableSent;},"haptic OUT position crossing deactivates both motors once");
        s->action([&](Runtime& r){r.move(m1,25,30);});waitFor([&]{return std::abs(s->snapshot().motors[m1].position-25)<.5;},"deactivate haptic then deliberate CSP move works");
        auto adapter=doc.adapters[0].id;s->connect(adapter,false);waitFor([&]{return !s->snapshot().motors[m0].connected;},"adapter disconnect clears connection state");s->connect(adapter,true);waitFor([&]{auto p=s->snapshot();return p.motors[m0].connected&&p.motors[m0].at>=0;},"adapter reconnect restores feedback");check(!s->snapshot().motors[m1].enableSent,"reconnect does not replay movement or enable");
        auto renamed=s->snapshot().document;renamed.motors[0].name="Renamed cupboard";renamed.events[0].name="Renamed timeline";renamed.events[8].stiffness=1.7;renamed.events[8].damping=.08;renamed.events[8].torqueLimit=.6;renamed.events[8].signB=-1;s->edit(renamed);check(s->snapshot().document.events[1].outputs[0]==m0,"rename preserves stable motor references");
        if(!reload){bool done=false,ok=false;app.engine->saveAsAsync(path,false,false,false,[&](FileBasedDocument::SaveResult r){done=true;ok=r==FileBasedDocument::savedOk;});waitFor([&]{return done;},"native Save As callback completes");check(ok&&path.existsAsFile(),"native noisette document saved");auto json=JSON::parse(path);check(json["midnightNative"]["motors"].size()==3,"Midnight hardware stored inside native project");
            auto demo=demonstration();auto savedDemo=app.engine->getJSONData();savedDemo.getDynamicObject()->removeProperty("layout");savedDemo.getDynamicObject()->setProperty("midnightNative",encodeDocument(demo));File demoFile=path.getParentDirectory().getParentDirectory().getChildFile("examples/Midnight_V01_Demo.noisette");demoFile.getParentDirectory().createDirectory();demoFile.replaceWithText(JSON::toString(savedDemo));
        }else check(renamed.motors[0].name=="Renamed cupboard","fresh-process reload retains renamed motor and hardware configuration");
        s->action([](Runtime& r){r.stopAll();});app.mainComponent->clear();std::cout<<"SUCCESS "<<checks<<" integration checks in "<<argv[1]<<std::endl;
    }catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;code=1;}
    app.mainComponent.reset();app.engine.reset();return code;
}
